# Campos de partida para las horas. Oficina puede crear más o borrarlos desde «Precios horas».
CAMPOS_INICIALES = ['Calefacción', 'Climatización', 'Electricidad', 'Fontanería', 'Fotovoltaica']


def crear_campos(apps, schema_editor):
    CampoHora = apps.get_model('gestion', 'CampoHora')
    for nombre in CAMPOS_INICIALES:
        CampoHora.objects.get_or_create(nombre=nombre)


def quitar_campos(apps, schema_editor):
    CampoHora = apps.get_model('gestion', 'CampoHora')
    CampoHora.objects.filter(nombre__in=CAMPOS_INICIALES, consumos__isnull=True).delete()



